ALL_OVERRIDES = {}
ALL_OVERRIDES.update(OVERRIDES_PART1)
ALL_OVERRIDES.update(OVERRIDES_PART2)
ALL_OVERRIDES.update(OVERRIDES_PART3)
ALL_OVERRIDES.update(OVERRIDES_PART4)
ALL_OVERRIDES.update(OVERRIDES_PART5)

print(f"Total overrides loaded: {len(ALL_OVERRIDES)}")

# Validate overrides
errors = []
for word_id, data in ALL_OVERRIDES.items():
    if not data.get("hw"):
        errors.append(f"{word_id}: missing hw")
    if data.get("pos") not in ["noun", "verb", "adj", "adv", "num", "intj", "prep", "pron", "conj", "det"]:
        errors.append(f"{word_id}: invalid pos {data.get('pos')}")
    vi = data.get("vi", "")
    if not vi:
        errors.append(f"{word_id}: empty vi")
    if len(vi) > 35:
        errors.append(f"{word_id}: vi length > 35: {len(vi)} chars: {vi}")
    ipa = data.get("ipa", "")
    if not ipa or not ipa.startswith("/") or not ipa.endswith("/"):
        errors.append(f"{word_id}: invalid ipa: '{ipa}'")

if errors:
    print(f"Validation FAILED with {len(errors)} errors:")
    for e in errors[:25]:
        print(" ", e)
    raise SystemExit(1)

# Now apply to batch-09.json
BATCH_FILE = "content/english/qa-batches/batch-09.json"
with open(BATCH_FILE, "r", encoding="utf-8") as f:
    batch_data = json.load(f)

records = batch_data["records"]
applied_count = 0

for i in range(2500, 3000):
    r = records[i]
    r_id = r["id"]
    if r_id in ALL_OVERRIDES:
        ov = ALL_OVERRIDES[r_id]
        if r["hw"].lower() != ov["hw"].lower():
            print(f"Mismatch at index {i}: record hw '{r['hw']}' vs override hw '{ov['hw']}'")
            raise SystemExit(1)
        r["pos"] = ov["pos"]
        r["vi"] = ov["vi"]
        r["ipa"] = ov["ipa"]
        applied_count += 1
    else:
        print(f"Missing override for record index {i}: {r_id} {r['hw']}")
        raise SystemExit(1)

print(f"Successfully applied {applied_count} overrides to records 2500-2999.")

# Update reviewedCount
batch_data["reviewedCount"] = 3000
batch_data["status"] = "in_progress"

with open(BATCH_FILE, "w", encoding="utf-8") as f:
    json.dump(batch_data, f, ensure_ascii=False, indent=2)

print("Batch 09 updated: reviewedCount is now 3000.")

